async function protect(context){await context.route('**/*',route=>{const r=route.request(),u=new URL(r.url());if(!['localhost','127.0.0.1'].includes(u.hostname)){network.push({blockedExternal:u.origin});return route.abort();}if(['POST','PUT','PATCH','DELETE'].includes(r.method())&&!u.pathname.startsWith('/__nextjs')){const allowed=/auth\/(login|refresh)/.test(u.pathname)||u.pathname==='/api/ocr-v2-lab';network.push({method:r.method(),path:u.pathname,allowed});if(!allowed)return route.abort();}return route.continue();});}
function observe(page){page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(['warning','error'].includes(m.type()))consoleMessages.push({type:m.type(),text:m.text()});});}
